// Executes a bundle generated by the Rust side inside a vm context with a fake window, and
// prints what the scripts recorded as JSON. Usage: node bundle_smoke.mjs <bundle.js>
import { readFileSync } from "node:fs";
import vm from "node:vm";
import { makeEnv, sleep } from "./harness.mjs";

const bundle = readFileSync(process.argv[2], "utf8");
const env = makeEnv({ store: { a: "from-store" } });
const ctx = vm.createContext({ window: env.W });
// Like a browser, globals of the page resolve through the window object.
env.W.window = env.W;
new vm.Script(bundle, { filename: "bundle.js" }).runInContext(ctx);
env.fireDCL();
await sleep(150);
console.log(JSON.stringify({ out: env.W.__out || null, errors: env.consoleCalls.error.map((e) => e.map(String)), calls: env.backend.calls.map((c) => c.path) }));
process.exit(0);
